MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickSignature);
  assert(exception != (ExceptionInfo *) NULL);

  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  size_t
    scene;

  /* Clone the image info */
  clone_info = CloneImageInfo(image_info);

  /* Prepare the filenames */
  clone_info->filename = (char *) filename;

  /* Set the adjoin flag based on the number of images */
  if (clone_info->adjoin && (GetImageListLength(images) > 1)) {
    image = CloneImageList(images, exception);
    scene = 0;
    do {
      if (clone_info->scene != 0) {
        (void) CopyMagickString(clone_info->filename,
                                GetImageProperty(clone_info->filename, image,
                                                 exception), MAGICK_PATH_MAX);
        clone_info->scene = scene;
      }
      status = WriteImage(clone_info, image, exception);
      if (status == MagickFalse)
        break;
      scene++;
      image = GetNextImageInList(image);
    } while (image != (Image *) NULL);
    DestroyImageList(image);
  }
  else {
    status = WriteImage(clone_info, images, exception);
  }

  /* Destroy the clone info */
  DestroyImageInfo(clone_info);

  return status;
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  (void) AcquireSemaphoreInfo();
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);
  status = MagickTrue;
  for (image = images; image != (Image *) NULL; image = GetNextImageInList(image))
  {
    char
      *file;

    file = CloneString(filename);
    if (file == (char *) NULL)
      {
        RelinquishSemaphoreInfo();
        return(MagickFalse);
      }
    if (image->scene != 0)
      {
        char
          *scene_filename;

        scene_filename = GetImageFilename(image, file, exception);
        if (scene_filename == (char *) NULL)
          {
            RelinquishSemaphoreInfo();
            return(MagickFalse);
          }
        file = scene_filename;
      }
    clone_info->adjoin = MagickFalse;
    status = WriteImage(clone_info, image, file, exception);
    file = RelinquishString(file);
    if (status == MagickFalse)
      break;
  }
  clone_info = DestroyImageInfo(clone_info);
  RelinquishSemaphoreInfo();
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  (void) memset(exception, 0, sizeof(*exception));
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);
  status = MagickTrue;
  for (image = images; image != (Image *) NULL; image = GetNextImageInList(image))
  {
    char
      *temp_filename;

    temp_filename = AcquireString(filename);
    (void) FormatString(temp_filename,"%s",filename);
    if (image_info->adjoin != MagickFalse)
    {
      char
        *scene_filename;

      scene_filename = GetImageSibling(temp_filename,images,image);
      temp_filename = scene_filename;
    }
    if (image->scene == 0)
      (void) ResetImageProgressMonitor(images,NULL,(MagickOffsetType) 0,
        (MagickOffsetType) 0);
    status = WriteImage(clone_info,image,temp_filename,exception);
    if (status == MagickFalse)
      break;
    if (image_info->adjoin != MagickFalse)
      (void) FreeImageSibling(temp_filename);
    (void) FreeString(&temp_filename);
  }
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickCoreSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickCoreSignature);
  (void) CloneString(&images->filename,filename);
  clone_info = (ImageInfo *) CloneImageInfo(image_info);
  status = MagickTrue;
  if (clone_info->adjoin != MagickFalse)
    for (image = GetFirstImageInList(images); image != (Image *) NULL;
         image = GetNextImageInList(image)) {
      Image
        *image_list;

      image_list = CloneImageList(image, exception);
      if (image_list == (Image *) NULL)
        break;
      (void) SetImageInfoFileName(clone_info, image->filename);
      status &= WriteImage(clone_info, image_list, exception);
      if (image->next == (Image *) NULL)
        break;
      (void) IncrementImageScene(image);
    }
  else
    status = WriteImage(clone_info, images, exception);
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception) {
  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickCoreSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickCoreSignature);
  assert(exception != (ExceptionInfo *) NULL);
  assert(exception->signature == MagickCoreSignature);

  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  ssize_t
    i;

  status = MagickTrue;
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return MagickFalse;
  GetExceptionInfo(exception);
  for (i = 0, image = images; image != (Image *) NULL; image = image->next) {
    char
      *unique_filename;

    clone_info = CloneImageInfo(image_info);
    if (clone_info == (ImageInfo *) NULL)
      return MagickFalse;
    unique_filename = AcquireUniqueFilename(filename);
    if (unique_filename == (char *) NULL)
      return MagickFalse;
    clone_info->filename = unique_filename;
    status = WriteImage(clone_info, image, exception);
    if (status == MagickFalse)
      break;
    i++;
    if (i < GetImageListLength(images))
      SyncImageList(images);
  }
  return status;
}
